new='''def _refundable(payment: Payment) -> Cents:
    if payment["gateway_ref"] is None:
        return Cents(0)
    return Cents(max(payment["amount"] - payment["refunded_amount"], 0))


def _credit_already_returned(ctx: Context, invoice_id: InvoiceId) -> bool:
    return any(e["reason"] == "refund" and e["invoice_id"] == invoice_id for e in ctx.store.ledger)


def refund_invoice(
    ctx: Context, invoice_id: InvoiceId, reason: str = "requested_by_customer", amount: Cents | None = None
) -> CreditNote:
    """Refund paid money on an invoice back to the original payment method.

    Without an amount, everything still refundable is refunded and applied account credit is returned.
    With an amount, only that much is refunded, taken from successful payments oldest first.
    """
    invoice = ctx.store.require_invoice(invoice_id)
    if invoice["status"] != "paid":
        raise InvalidStateError("only paid invoices can be refunded")
    payments = successful_payments(ctx, invoice["id"])
    money_credited = Cents(
        sum(note["amount"] for note in ctx.store.credit_notes_for(invoice_id) if not note["refunded"])
    )
    refundable = Cents(max(sum(_refundable(p) for p in payments) - money_credited, 0))
    credit_back = Cents(0)
    if amount is None:
        if not _credit_already_returned(ctx, invoice_id):
            credit_back = invoice["credit_applied"]
        if refundable == 0 and credit_back == 0:
            raise InvalidStateError("invoice has nothing left to refund")
        target = refundable
    else:
        if amount <= 0:
            raise ValidationError("refund amount must be positive")
        if refundable == 0:
            raise InvalidStateError("invoice has nothing left to refund")
        if amount > refundable:
            raise ValidationError(f"cannot refund more than {refundable} on this invoice")
        target = amount
    refunded = Cents(0)
    for payment in sorted(payments, key=lambda p: p["created_at"]):
        take = Cents(min(_refundable(payment), target - refunded))
        if take <= 0:
            continue
        result = ctx.gateway.refund(payment["gateway_ref"], take)
        if not result["ok"]:
            raise InvalidStateError(f"gateway refused refund for payment {payment['id']}")
        payment["refunded_amount"] = Cents(payment["refunded_amount"] + take)
        payment["status"] = "refunded" if payment["refunded_amount"] >= payment["amount"] else "partially_refunded"
        refunded = Cents(refunded + take)
        emit(ctx, "payment.refunded", {"payment": payment_json(payment)})
    if credit_back > 0:
        add_entry(ctx, invoice["customer_id"], credit_back, "refund", invoice["id"])
    return _credit_note(ctx, invoice_id, Cents(refunded + credit_back), reason, True)


'''
